<template>
  <main class="canvas-home layout-design-home ordered-home" :class="{'ordered-editing':editing}" data-ordered-home>
    <header class="lab-header"><router-link class="lab-brand" :to="target('/')"><span class="canvas-logo">Q<i></i></span><span>Quickstart<small>iStoreOS</small></span></router-link><span class="lab-header-context">{{t('我的网络空间','My network space')}}</span><div class="lab-header-actions"><button @click="toggleTheme" :aria-label="t('切换主题','Toggle theme')">{{theme==='dark'?'☼':'◐'}}</button><details class="lab-scenes"><summary>{{t('设计预览','Design preview')}}</summary><div><small>{{t('合成数据 · 刷新恢复示例','Synthetic data · Reload resets')}}</small><label>{{t('布局示例','Layout sample')}}<select aria-label="布局示例" :value="route.query.preset||'normal'" @change="changeSample"><option value="normal">{{t('默认并排','Default rows')}}</option><option value="stacked">{{t('左大右上下','Tall left')}}</option><option value="mirrored">{{t('左上下右大','Tall right')}}</option><option value="services">{{t('三列服务','Three services')}}</option></select></label><label>{{t('数据场景','Scenario')}}<select aria-label="数据场景" :value="demo.scenario" @change="changeQuery('scenario',$event)"><option v-for="scene in scenes" :key="scene[0]" :value="scene[0]">{{t(scene[1],scene[2])}}</option></select></label><label>{{t('地址分配方','Address allocator')}}<select aria-label="地址分配方" :value="demo.authority" @change="changeQuery('authority',$event)"><option value="external">{{t('其他主路由','Another router')}}</option><option value="local">{{t('本机','This router')}}</option><option value="unknown">{{t('待确认','Unknown')}}</option></select></label><button @click="toggleLanguage">中文 / English</button></div></details><button ref="editButton" class="lab-edit-button" @click="editing?cancel():begin()" :aria-pressed="editing" :aria-label="t('自定义首页','Customize home')"><StudioGlyph name="tune"/><span>{{t('自定义首页','Customize home')}}</span></button></div></header>
    <div class="lab-intro"><div><span class="lab-eyebrow">{{t('首页概览','HOME OVERVIEW')}}</span><h1>{{t('连接、设备与生活','Your connected home')}}</h1></div><span class="lab-intro-status"><i :class="{ready:data.network?.internetConnected&&!errors.network}"></i>{{t('我的网络','My network')}}<small>{{t('设计示例','Design sample')}}</small></span></div>

    <section v-if="editing" class="ordered-editor" aria-label="首页布局编辑器">
      <div class="ordered-editor-heading"><div><strong>{{t('按你的习惯，安排首页','Make this space yours')}}</strong><p>{{t('先选一行，再选布局与卡片。修改只影响本次预览。','Select a row, then its layout and cards. Preview-only changes.')}}</p></div><button @click="undo" :disabled="!history.length" data-undo>{{t('撤销','Undo')}}</button><button @click="mutate(()=>recommended())" data-reset>{{t('恢复推荐','Restore recommended')}}</button></div>
      <div class="ordered-width"><label>{{t('内容预览宽度','Content preview width')}}<input type="range" min="292" :max="Math.max(292,availableWidth)" step="1" :value="Math.min(previewWidth||availableWidth,availableWidth)" @input="previewWidth=Number(($event.target as HTMLInputElement).value)" aria-label="内容预览宽度"/><output>{{Math.round(contentWidth)}}px</output></label><button @click="previewWidth=0">{{t('自动宽度','Auto width')}}</button><span>{{t('缩窄不改写你的布局，变宽后恢复','Narrow previews preserve the wide layout')}}</span></div>
      <div class="ordered-row-picker"><button v-for="(row,index) in draft" :key="row.id" :class="{active:row.id===selected}" @click="selected=row.id" :data-select-row="row.id">{{t('第','Row ')}}{{index+1}}{{t('行','')}}</button><button @click="addRow" data-add-row>＋ {{t('添加行','Add row')}}</button><button @click="library=true" data-open-library>{{t('模块清单','Modules')}} · {{hidden.length}}</button></div>
      <template v-if="selectedRow">
        <div class="ordered-template-list" aria-label="行布局样式"><button v-for="preset in templates" :key="preset.id" @click="setTemplate(preset.id)" :class="{active:selectedRow.template===preset.id}" :aria-pressed="selectedRow.template===preset.id" :data-template="preset.id"><span class="ordered-miniature" :class="preset.id"><i v-for="(n,index) in preset.slots" :key="index"><b v-for="k in n" :key="k"></b></i></span>{{t(preset.zh,preset.en)}}</button></div>
        <div class="ordered-row-controls"><label>{{t('行高','Row height')}}<select aria-label="行高" :value="selectedRow.height" @change="setHeight(Number(($event.target as HTMLSelectElement).value))"><option v-for="n in heightOptions" :key="n" :value="n">{{n}} px</option></select></label><template v-if="selectedRow.columns.length>1"><label>{{t('列宽','Column widths')}}<select aria-label="列宽比例" :value="selectedRow.columns.map(c=>c.weight).join('/')" @change="setWeights(String(($event.target as HTMLSelectElement).value).split('/').map(Number))"><option v-for="ratio in widthPresets" :key="ratio.join('/')" :value="ratio.join('/')">{{ratio.join(' / ')}}</option></select></label><label>{{t('第一列','First column')}}<input type="range" min="20" max="80" step="5" :value="selectedRow.columns[0].weight" @change="setFirstWeight(Number(($event.target as HTMLInputElement).value))" aria-label="第一列宽度"/></label></template><div class="ordered-row-actions"><button @click="moveRow(-1)" :disabled="selectedIndex===0" :aria-label="t('整行上移','Move row up')">↑</button><button @click="moveRow(1)" :disabled="selectedIndex===draft.length-1" :aria-label="t('整行下移','Move row down')">↓</button><button @click="hideRow" data-hide-row>{{t('收起整行','Hide row')}}</button></div></div>
        <div class="ordered-slot-list"><div v-for="(column,ci) in selectedRow.columns" :key="ci" class="ordered-slot-column"><label v-for="(id,si) in column.cards" :key="si"><span>{{t('第','Column ')}}{{ci+1}}{{t('列','')}}{{column.cards.length===2?(si===0?t(' · 上',' · Top'):t(' · 下',' · Bottom')):''}}</span><select :value="id||''" @change="assign(ci,si,($event.target as HTMLSelectElement).value as WidgetId)" :aria-label="'slot-'+ci+'-'+si" :data-slot-select="ci+'-'+si"><option value="">{{t('空位 / 隐藏','Empty / hidden')}}</option><option v-for="item in widgetDefinitions" :key="item.id" :value="item.id">{{t(item.zh,item.en)}}{{visible.includes(item.id)&&item.id!==id?t(' · 移动到这里',' · Move here'):''}}</option></select></label><label v-if="column.cards.length===2">{{t('上下比例','Top / bottom')}}<select :value="column.split" @change="setSplit(ci,Number(($event.target as HTMLSelectElement).value))" :aria-label="'stack-ratio-'+ci"><option :value="50">50 / 50</option><option :value="60">60 / 40</option><option :value="40">40 / 60</option></select></label></div></div>
        <p class="ordered-editor-hint">{{t('卡片支持拖动交换，也可用上方选择框移动。上下组合使用紧凑摘要；留空的槽位不会出现在首页。','Drag to swap, or use the selectors to move cards. Stacks use compact summaries. Empty slots stay off the home page.')}}</p>
      </template>
    </section>
    <p class="ordered-notice" v-if="notice" role="status" data-layout-notice>{{notice}}</p>

    <div class="lab-available" ref="availableElement"><div class="lab-content ordered-content" ref="contentElement" :style="{maxWidth:previewWidth?previewWidth+'px':undefined}">
      <section v-for="row in actualRows" :key="row.id" class="ordered-row" :class="{selected:editing&&row.source===selected}" :style="rowStyle(row)" :data-ordered-row="row.id" :data-row-source="row.source">
        <div v-for="(column,ci) in row.columns" :key="column.source" class="ordered-column" :style="columnStyle(column)" :data-ordered-column="ci">
          <div v-for="(id,si) in column.cards" :key="id" class="ordered-card" :class="{drop:dropTarget===id}" :data-ordered-card="id" @dragover.prevent="dropTarget=id" @dragleave="dropTarget=null" @drop.prevent="dropCard(id)">
            <div v-if="editing" class="ordered-card-controls"><button draggable="true" @dragstart="startDrag($event,id)" @dragend="dragged=null;dropTarget=null" @click="selectCard(row.source,id)" :aria-label="t('选择或拖动','Select or drag ')+name(id)" :data-drag-card="id">⠿ {{name(id)}}</button><button @click="hideCard(id)" :aria-label="t('隐藏','Hide ')+name(id)">×</button></div>
            <CompactPreviewCard v-if="column.compact&&compactIds.includes(id)" :id="id" :data="data" :errors="errors" @navigate="go" @retry="retry"/>
            <LayoutPreviewCard v-else :id="id" :data="data" :errors="errors" :devices="devices" :theme="theme" contained @navigate="go" @device="openDevice" @retry="retry"/>
            <button v-if="editing&&column.cards.length===2&&si===0" class="ordered-stack-handle" :aria-label="t('调整上下比例','Adjust stack ratio')" @pointerdown="startStack($event,row.source,column.source)" @keydown.up.prevent="nudgeSplit(row.source,column.source,-5)" @keydown.down.prevent="nudgeSplit(row.source,column.source,5)">⋯</button>
          </div>
        </div>
        <template v-if="editing&&row.columns.length>1"><button v-for="(_,index) in row.columns.slice(0,-1)" :key="index" class="ordered-column-handle" :style="{left:'clamp(9px,'+divider(row,index)+'px,calc(100% - 9px))'}" :aria-label="t('调整列宽','Adjust column widths')+' '+(index+1)" @pointerdown="startWidth($event,row,index)" @keydown.left.prevent="nudgeWidth(row.source,row.columns[index].source,-5)" @keydown.right.prevent="nudgeWidth(row.source,row.columns[index].source,5)">⋮</button></template>
      </section>
      <section v-if="!actualRows.length" class="ordered-empty"><StudioGlyph name="grid"/><h2>{{t('首页，由你安排','A home of your own')}}</h2><p>{{t('添加常看的模块，也可以随时恢复推荐布局。','Add the things you check most, or restore the recommended layout.')}}</p><button @click="editing?library=true:begin()">{{t('添加模块','Add modules')}}</button></section>
    </div></div>
    <footer class="lab-footer"><span>Quickstart <i>/</i> {{t('有序布局 · 设计预览','Ordered layout · Design preview')}}</span><HomeApplications collapsed :fallback-entries="quickEntrances" @navigate="go"/></footer>
    <div v-if="editing" class="ordered-savebar"><span>{{t('布局草稿 · 仅本次预览','Layout draft · Preview only')}}</span><button @click="cancel" data-cancel>{{t('取消','Cancel')}}</button><button @click="apply" class="primary" data-apply>{{t('应用布局','Apply layout')}}</button></div>
    <template v-if="library"><div class="ordered-modal-backdrop" @click="closeLibrary"></div><section ref="libraryElement" class="ordered-library" role="dialog" aria-modal="true" :aria-label="t('首页模块','Home modules')" @keydown="libraryKeyboard"><header><div><small>{{t('首页内容','HOME CONTENT')}}</small><h2>{{t('留下你关心的','Keep what matters')}}</h2></div><button @click="closeLibrary" :aria-label="t('关闭模块清单','Close modules')">×</button></header><p>{{t('显示的模块可以关闭；隐藏模块重新开启后独占新行。','Hide visible modules; restored modules start on a new row.')}}</p><div class="ordered-library-list"><label v-for="item in widgetDefinitions" :key="item.id"><StudioGlyph :name="item.glyph"/><span>{{t(item.zh,item.en)}}<small>{{compactIds.includes(item.id)?t('支持上下组合摘要','Compact stack available'):t('标准卡片','Standard card')}}</small></span><input type="checkbox" :checked="visible.includes(item.id)" @change="toggleModule(item.id)" :data-module-toggle="item.id"/></label></div><footer><button @click="hideAll">{{t('全部收起','Hide all')}}</button><button class="primary" @click="closeLibrary">{{t('完成','Done')}}</button></footer></section></template>
  </main>
</template>
<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import StudioGlyph from './StudioGlyph.vue'
import LayoutPreviewCard from './LayoutPreviewCard.vue'
import CompactPreviewCard from './CompactPreviewCard.vue'
import HomeApplications from './HomeApplications.vue'
import {useStudioModel} from './studioModel'
import {demo} from './fixtures'
import {quickEntrances} from './canvasLayout'
import {homeApplicationSession} from './homeApplications'
import {getTheme} from '../utils/theme'
import {widgetDefinitions,widget,type WidgetId} from './rowLayout'
import {templates,clone,compactIds,orderedSession,recommended,makeRow,visibleIds,layoutIssue,rowMinimum,changeTemplate,renderRows,type Template,type OrderedRow,type ActualRow,type ActualColumn} from './orderedLayout'
const route=useRoute(),router=useRouter(),english=window.vue_lang==='en',t=(zh:string,en:string)=>english?en:zh,name=(id:WidgetId)=>t(widget(id).zh,widget(id).en)
const editing=ref(false),draft=ref(clone(orderedSession.value)),history=ref<OrderedRow[][]>([]),selected=ref(draft.value[0]?.id||''),notice=ref(''),previewWidth=ref(0),theme=ref(getTheme())
const layout=computed(()=>editing.value?draft.value:orderedSession.value),visible=computed(()=>visibleIds(layout.value)),hidden=computed(()=>widgetDefinitions.filter(w=>!visible.value.includes(w.id)))
const selectedIndex=computed(()=>draft.value.findIndex(r=>r.id===selected.value)),selectedRow=computed(()=>draft.value[selectedIndex.value])
const heightOptions=computed(()=>[152,240,280,320,340,360,400,480,560].filter(n=>n!==152||selectedRow.value?.template==='single'))
const widthPresets=computed(()=>{const values=selectedRow.value?.columns.length===3?[[34,33,33],[50,25,25],[25,50,25]]:[[50,50],[60,40],[65,35],[40,60]],current=selectedRow.value?.columns.map(c=>c.weight)||[];return values.some(v=>v.join('/')===current.join('/'))?values:[current,...values]})
const readerLayout=computed(()=>visible.value.map(id=>({id,enabled:true})))
const {data,errors,devices,retry}=useStudioModel(readerLayout,['traffic'])
const availableElement=ref<HTMLElement|null>(null),contentElement=ref<HTMLElement|null>(null),availableWidth=ref(1160),contentWidth=ref(1160)
const actualRows=computed(()=>renderRows(layout.value,contentWidth.value,homeApplicationSession.favorites.length))
const editButton=ref<HTMLButtonElement|null>(null),library=ref(false),libraryElement=ref<HTMLElement|null>(null)
function begin(){draft.value=clone(orderedSession.value);history.value=[];editing.value=true;selected.value=draft.value[0]?.id||'';notice.value=''}
function cancel(){editing.value=false;draft.value=clone(orderedSession.value);notice.value=t('已取消，恢复本次预览已应用的布局。','Cancelled. Applied preview layout restored.');editButton.value?.focus()}
function apply(){const issue=layoutIssue(draft.value);if(issue){warn(issue);return}orderedSession.value=clone(draft.value.filter(r=>visibleIds([r]).length));editing.value=false;notice.value=t('布局已应用到本次预览；刷新恢复示例。','Layout applied in this preview. Reload resets it.');editButton.value?.focus()}
function warn(issue:string){notice.value=issue==='duplicate'?t('同一模块不能重复出现。','A module can only appear once.'):t('这个组合至少需要 ','This combination needs at least ')+issue+t('px 行高。请先增加行高，或换用其他卡片／布局。','px height. Increase the row height or choose other cards/layouts.')}
function mutate(change:(rows:OrderedRow[])=>OrderedRow[]){const before=clone(draft.value),next=change(clone(before)),issue=layoutIssue(next);if(issue){warn(issue);return false}history.value=[...history.value.slice(-29),before];draft.value=next;if(!next.some(r=>r.id===selected.value))selected.value=next[0]?.id||'';notice.value='';return true}
function undo(){const previous=history.value.pop();if(previous){draft.value=previous;if(!previous.some(r=>r.id===selected.value))selected.value=previous[0]?.id||'';notice.value=t('已撤销上一次布局修改。','Last layout change undone.')}}
function setTemplate(template:Template){mutate(rows=>changeTemplate(rows,selected.value,template))}
function setHeight(value:number){mutate(rows=>{rows[selectedIndex.value].height=value;return rows})}
function setWeights(weights:number[]){mutate(rows=>{rows[selectedIndex.value].columns.forEach((c,i)=>c.weight=weights[i]);return rows})}
function setFirstWeight(value:number){const columns=selectedRow.value.columns;setWeights(columns.length===2?[value,100-value]:[value,Math.floor((100-value)/2),100-value-Math.floor((100-value)/2)])}
function setSplit(ci:number,value:number){const row=selectedRow.value,column=row.columns[ci],minimum=column.cards.map(id=>id?compactIds.includes(id)?148:widget(id).minHeight:0);if(minimum[0]>(row.height-18)*value/100||minimum[1]>(row.height-18)*(100-value)/100){notice.value=t('上下比例已达到卡片最小高度限制。','Stack ratio is limited by card minimum heights.');return}mutate(rows=>{rows[selectedIndex.value].columns[ci].split=value;return rows})}
function assign(ci:number,si:number,id:WidgetId){const rowId=selected.value;mutate(rows=>{const column=rows.find(r=>r.id===rowId)!.columns[ci],old=column.cards[si];for(const row of rows)for(const c of row.columns)for(let i=0;i<c.cards.length;i++)if(id&&c.cards[i]===id)c.cards[i]=old||null;column.cards[si]=id||null;return rows})}
function hideCard(id:WidgetId){mutate(rows=>{for(const row of rows)for(const c of row.columns)c.cards=c.cards.map(v=>v===id?null:v);return rows})}
function toggleModule(id:WidgetId){if(visible.value.includes(id)){hideCard(id);return}const row=makeRow([id],'single',Math.max(320,widget(id).singleHeight));if(mutate(rows=>[...rows,row]))selected.value=row.id}
function addRow(){const row=makeRow();mutate(rows=>[...rows,row]);selected.value=row.id}
function hideRow(){mutate(rows=>rows.filter(r=>r.id!==selected.value))}
function hideAll(){mutate(()=>[])}
function moveRow(delta:number){mutate(rows=>{const index=selectedIndex.value;[rows[index],rows[index+delta]]=[rows[index+delta],rows[index]];return rows})}
function selectCard(row:string,id:WidgetId){selected.value=row;notice.value=name(id)+t(' · 在上方选择框中移动，或拖到另一张卡片上交换。',' · Move with the selectors above, or drag onto another card to swap.')}
const dragged=ref<WidgetId|null>(null),dropTarget=ref<WidgetId|null>(null)
function startDrag(event:DragEvent,id:WidgetId){dragged.value=id;event.dataTransfer?.setData('text/plain',id);if(event.dataTransfer)event.dataTransfer.effectAllowed='move'}
function dropCard(id:WidgetId){const from=dragged.value;if(from&&from!==id)mutate(rows=>{for(const row of rows)for(const c of row.columns)c.cards=c.cards.map(v=>v===from?id:v===id?from:v);return rows});dragged.value=null;dropTarget.value=null}
function rowStyle(row:ActualRow){return {height:row.height+'px',gridTemplateColumns:row.columns.map(c=>'minmax('+Math.min(contentWidth.value,Math.max(...c.cards.map(id=>widget(id).minWidth)))+'px,'+c.weight+'fr)').join(' ')}}
function columnStyle(column:ActualColumn){return {gridTemplateRows:column.cards.length===1?'minmax(0,1fr)':`minmax(0,${column.split}fr) minmax(0,${100-column.split}fr)`}}
function divider(row:ActualRow,index:number){const element=contentElement.value?.querySelector<HTMLElement>('[data-ordered-row="'+row.id+'"]'),columns=element?.querySelectorAll<HTMLElement>('.ordered-column');if(!element||!columns?.[index])return 0;return columns[index].getBoundingClientRect().right-element.getBoundingClientRect().left+9}
let finishGesture:(()=>void)|undefined
function gesture(event:PointerEvent,move:(dx:number,dy:number)=>void,done:()=>void){event.preventDefault();finishGesture?.();const x=event.clientX,y=event.clientY;const onMove=(e:PointerEvent)=>move(e.clientX-x,e.clientY-y),finish=()=>{window.removeEventListener('pointermove',onMove);window.removeEventListener('pointerup',finish);window.removeEventListener('pointercancel',finish);finishGesture=undefined;done()};finishGesture=finish;window.addEventListener('pointermove',onMove);window.addEventListener('pointerup',finish);window.addEventListener('pointercancel',finish)}
function startWidth(event:PointerEvent,actual:ActualRow,index:number){const before=clone(draft.value),row=draft.value.find(r=>r.id===actual.source)!,a=actual.columns[index].source,b=actual.columns[index+1].source,start=row.columns[a].weight,total=start+row.columns[b].weight;const element=(event.currentTarget as HTMLElement).parentElement!,width=element.clientWidth-18*(actual.columns.length-1),sum=actual.columns.reduce((s,c)=>s+c.weight,0);gesture(event,dx=>{const value=Math.max(15,Math.min(total-15,Math.round((start+dx/width*sum)/5)*5));row.columns[a].weight=value;row.columns[b].weight=total-value},()=>history.value=[...history.value.slice(-29),before])}
function nudgeWidth(id:string,index:number,delta:number){selected.value=id;mutate(rows=>{const row=rows.find(r=>r.id===id)!,next=index+1;if(!row.columns[next])return rows;const total=row.columns[index].weight+row.columns[next].weight,value=Math.max(15,Math.min(total-15,row.columns[index].weight+delta));row.columns[index].weight=value;row.columns[next].weight=total-value;return rows})}
function nudgeSplit(id:string,index:number,delta:number){selected.value=id;setSplit(index,Math.max(20,Math.min(80,selectedRow.value.columns[index].split+delta)))}
function startStack(event:PointerEvent,id:string,index:number){selected.value=id;const before=clone(draft.value),row=selectedRow.value,column=row.columns[index],start=column.split,usable=row.height-18;gesture(event,(_,dy)=>{const value=Math.round((start+dy/usable*100)/5)*5;const minimum=column.cards.map(card=>card?compactIds.includes(card)?148:widget(card).minHeight:0);column.split=Math.max(Math.ceil(minimum[0]/usable*20)*5,Math.min(Math.floor((1-minimum[1]/usable)*20)*5,value))},()=>history.value=[...history.value.slice(-29),before])}
const target=(path:string,device?:string)=>({path,query:{...route.query,layout:'ordered',variant:'rows',device,filter:path==='/devicemanagement'?'all':undefined}})
function go(path:string){if(editing.value){notice.value=t('请先应用或取消布局草稿，再打开详情。','Apply or cancel the layout draft before opening details.');return}void router.push(target(path))}
function openDevice(id:string){if(editing.value){notice.value=t('请先应用或取消布局草稿，再打开设备。','Apply or cancel the draft before opening a device.');return}void router.push(target('/devicemanagement',id))}
function toggleTheme(){const value=theme.value==='dark'?'light':'dark';document.body.setAttribute('theme',value);void router.replace({query:{...route.query,theme:value}})}
function toggleLanguage(){if(editing.value){notice.value=t('切换语言会刷新示例，请先结束布局编辑。','Changing language reloads the sample. Finish editing first.');return}location.href=router.resolve({path:'/',query:{...route.query,layout:'ordered',variant:'rows',lang:english?'zh-cn':'en'}}).href}
function changeQuery(key:string,event:Event){demo.recovered=false;void router.replace({query:{...route.query,[key]:(event.target as HTMLSelectElement).value}})}
function changeSample(event:Event){if(editing.value){notice.value=t('切换示例会刷新布局，请先应用或取消草稿。','Changing the sample reloads the layout. Apply or cancel first.');return}location.href=router.resolve({path:'/',query:{...route.query,layout:'ordered',variant:'rows',preset:(event.target as HTMLSelectElement).value}}).href}
let libraryOpener:HTMLElement|null=null
watch(library,async open=>{if(open){libraryOpener=document.activeElement as HTMLElement;await nextTick();libraryElement.value?.querySelector<HTMLButtonElement>('button')?.focus()}else libraryOpener?.focus({preventScroll:true})})
function closeLibrary(){library.value=false}
function libraryKeyboard(event:KeyboardEvent){if(event.key==='Escape'){event.stopPropagation();closeLibrary()}if(event.key==='Tab'){const controls=Array.from(libraryElement.value?.querySelectorAll<HTMLElement>('button,input')||[]),first=controls[0],last=controls[controls.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}}
watch(()=>route.query.theme,()=>theme.value=getTheme())
let observer:ResizeObserver|undefined
onMounted(()=>{observer=new ResizeObserver(entries=>{for(const e of entries){if(e.target===availableElement.value)availableWidth.value=e.contentRect.width;if(e.target===contentElement.value)contentWidth.value=e.contentRect.width}});if(availableElement.value)observer.observe(availableElement.value);if(contentElement.value)observer.observe(contentElement.value);Object.defineProperty(window,'__quickstartOrdered',{configurable:true,get:()=>({editing:editing.value,applied:clone(orderedSession.value),draft:clone(draft.value),visible:visible.value,width:contentWidth.value,actual:actualRows.value,minimum:selectedRow.value?rowMinimum(selectedRow.value):0})})})
onUnmounted(()=>{observer?.disconnect();finishGesture?.();delete (window as any).__quickstartOrdered})
